function loadOrder(deps) {
  const order = [];
  const state = {};
  let cyclic = false;

  function visit(name) {
    if (state[name] === 2) return;
    if (state[name] === 1) {
      cyclic = true;
      return;
    }
    state[name] = 1;
    for (const d of [...(deps[name] || [])].sort()) visit(d);
    state[name] = 2;
    order.push(name);
  }

  for (const name of Object.keys(deps).sort()) visit(name);
  return cyclic ? null : order;
}

